import { decimal, implied, money, percent, signed, oddsLabel, probabilityToAmerican, fractionalKellyStake, arbitrageRows, middleRows, fantasySlip, plausibleEv, marketRowsOf } from './ev-core.js';
import { startsWithin, oddsWithin } from './ev-filters.js?v=2';
import { DEVIG_METHODS, SUITE_SETTING_DEFAULTS as defaults, suiteSettings, quoteAvailable, passesFilters, marketIdentity, consensusPrice, computeAdvancedEv, projectProbability, constrainedArb, middleOutcomes, advancedParlay, performanceSummary } from './ev-advanced-math.js';
import { readBets, writeBets, validateBet, betReturns } from './bet-utils.js?v=4';
import { createEvOperations } from './ev-operations.js?v=2';
import { createEvMarketViews } from './ev-market-views.js?v=2';
import { createEvLedger, suiteLedgerStorage } from './ev-ledger.js?v=2';
import { createEvFantasyLab } from './ev-fantasy-lab.js?v=2';

export const EV_SUITE_TOOLS = [
  ['Records','ledger','Ticket details & grading','Record tickets, grade individual legs, and keep notes with each selection.'],
  ['Workspace','settings','Pricing & saved filters','Choose reference books, weighting, limits, and display preferences.'],
  ['Workspace','performance','Profit, ROI & CLV','Review your recorded results, open exposure, and closing prices.'],
  ['Workspace','history','Line history','Compare observed price and line movements across books.'],
  ['Fantasy','fantasy-lab','Fantasy market comparison','Compare app lines with sportsbook fair probabilities and custom payout rules.'],
  ['Research','wallets','Wallet watchlist','Follow recorded prediction-market wallets and positions.'],
  ['Research','lineups','Lineup dropper','Compare lineup observations, independent projections, and older book quotes.'],
  ['Builders','promotions','Promotions & calculators','Manage offers and calculate bonuses, insurance, boosts, and bankroll exposure.'],
  ['Workspace','alerts','Alert center','Save threshold watches and review local notifications.'],
  ['Workspace','connections','Coverage & account','Data health, account preferences, issue reports, and connection readiness.']
];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = value => value === '' || value == null ? null : Number.isFinite(Number(value)) ? Number(value) : null;
// Without a saved maximum, returns above 15% are hidden as data errors, as on the Arbitrage board.
const ARB_DEFAULT_MAX_PERCENT = 15, MIDDLE_ROWS = 100;
const id = () => crypto.randomUUID();
const label = q => [q.player || q.event,q.market,q.side,q.line].filter(x=>x!==''&&x!=null).join(' · ');
const btn = (text,action,record='',extra='') => `<button type="button" data-suite-action="${action}" data-id="${esc(record)}" ${extra}>${text}</button>`;
const options = (values,current) => values.map(v=>{const [value,title]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}" ${String(current??'')===String(value)?'selected':''}>${esc(title)}</option>`;}).join('');
const field = (title,name,value='',type='text',extra='') => `<label>${esc(title)}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const select = (title,name,values,value) => `<label>${esc(title)}<select name="${name}">${options(values,value)}</select></label>`;
const check = (title,name,checked) => `<label class="evx-check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${esc(title)}</label>`;
const table = (heads,rows) => `<div class="evx-table-wrap"><table class="evx-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}"><div class="evx-empty">No matching records. Add or import data, or adjust your filters.</div></td></tr>`}</tbody></table></div>`;
const panel = (title,body,note='') => `<section class="evx-panel"><header><h3>${esc(title)}</h3>${note?`<p>${esc(note)}</p>`:''}</header>${body}</section>`;
const safeURL = value => {try {const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
const download = (data,name,type='application/json') => {const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const csvCell = value => '"'+String(value??'').replace(/^[\s]*[=+@-]/,m=>"'"+m).replaceAll('"','""')+'"';

export function createEvSuite(host) {
  const localStorage = suiteLedgerStorage;
  const nativeViews = new Set(host.nativeViews || []);
  const nativeLabel = () => 'Table';
  let message='', refreshTimer=null, dialogContext=null, lastRefresh=0, installPrompt=null;
  function root() {
    const state=host.getState();
    if (!state.suite || typeof state.suite!=='object' || Array.isArray(state.suite)) state.suite={};
    const s=state.suite;
    for(const key of ['settings','flags','betMeta','toolSettings']) if(!s[key]||typeof s[key]!=='object'||Array.isArray(s[key]))s[key]={};
    for(const key of ['presets','watchRules','alertLog','reports','builderIds'])if(!Array.isArray(s[key]))s[key]=[];
    return s;
  }
  const settings = () => suiteSettings(root().settings);
  function save(redraw=true) {host.setBuilderIds?.([...root().builderIds]);if(host.save()===false)throw Error('Changes remain in this open workspace, but could not be saved. Export your records before leaving.');if(redraw)host.redraw();}
  const operations=createEvOperations({getState:host.getState,save:()=>save(false),redraw:host.redraw,navigate:host.navigate});
  const markets=createEvMarketViews({getState:host.getState,save:()=>save(false),redraw:host.redraw,navigate:host.navigate,getSettings:settings});
  const ledger=createEvLedger({getState:host.getState,save:()=>save(false),redraw:host.redraw,navigate:key=>host.navigate(key==='tracker'?'ledger':key),getSettings:settings});
  const fantasy=createEvFantasyLab({getState:host.getState,save:()=>save(false),redraw:host.redraw,navigate:host.navigate,getSettings:settings,onTrack:(quotes,options)=>ledger.openTracking(quotes,options)});
  const openTracking=(quotes,options={})=>ledger.openTracking(quotes,options);
  function displayOdds(value) {const d=decimal(value);if(!Number.isFinite(d))return '—';return settings().oddsFormat==='decimal'?d.toFixed(3):settings().oddsFormat==='fractional'?`${(d-1).toFixed(2)}/1`:oddsLabel(value);}
  // The Scope settings limit every tool, as their description says, not only Positive EV.
  function quoteVisible(q) {const s=settings(),f=root().flags[q.id]||{};return (s.showHidden||!f.hidden)&&(!s.hideTaken||!f.taken)&&quoteAvailable(q,s)&&passesFilters(q,s);}
  function contextMatch(q) {const c=host.getContext?.()||{},positive=['ev-pre','ev-live'].includes(host.getTool?.()),d=c.designFilters||{},league=positive?c.league:d.league,date=positive?c.date:d.date,maxOdds=positive?c.maxOdds:d.maxOdds;return (!c.sport||q.sport===c.sport)&&(!c.marketType||q.type===c.marketType)&&(!league||(q.league||q.sport)===league)&&(!maxOdds||maxOdds==='all'||Number(q.odds)<=Number(maxOdds))&&(!date||date==='all'||startsWithin(q,date))&&(!c.search||[q.event,q.player,q.market,q.side,q.book,q.league].some(v=>String(v||'').toLowerCase().includes(c.search.toLowerCase())))&&(!host.bookSelected||host.bookSelected(q.book));}
  function qState(q) {const g=q.gameState||{};const pieces=[g.awayScore!=null&&g.homeScore!=null?`${g.awayScore}–${g.homeScore}`:'',g.period,g.clock,g.inPlay===true?'In play':g.inPlay===false?'Stoppage':'',g.down!=null?`${g.down} & ${g.distance??'?'}`:'',g.inning!=null?`Inning ${g.inning}`:'',g.count,g.runners!=null?`Runners ${g.runners}`:'',g.fouls!=null?`Fouls ${g.fouls}`:'',g.timeouts!=null?`Timeouts ${g.timeouts}`:'',g.cards,g.penalties].filter(v=>v!==''&&v!=null);return pieces.length?pieces.map(esc).join(' · '):q.live?'Live record · game state not supplied':'Pregame';}
  function controls(q,tool='ev') {
    const f=root().flags[q.id]||{};
    return `<div class="evx-actions">${btn('Track','track',q.id,`data-tool="${esc(tool)}"`)}<button type="button" data-detail="${esc(q.id)}">Compare</button>${btn(f.pin?'Pinned':'Pin','pin',q.id,`aria-pressed="${Boolean(f.pin)}"`)}<details class="evx-more"><summary aria-label="More actions">More</summary><div>${btn(f.hidden?'Restore':'Hide','hide',q.id)}${btn(f.taken?'Taken':'Mark taken','taken',q.id,`aria-pressed="${Boolean(f.taken)}"`)}${btn('History','history',q.id)}${btn('Bet link','link',q.id)}${btn('Record details','quote-meta',q.id)}${btn('Report','report',q.id)}</div></details></div>`;
  }
  function priceDiagnostic(row) {return `<details class="evx-diagnostic"><summary>${row.consensus?.bookCount||row.consensus?.books?.length||0} reference books${row.estimated?' · estimated line':''}</summary><p>${esc(row.estimated?row.projection?.label||'Interpolated between recorded thresholds':`${settings().devigMethod} no-vig method`)}</p>${(row.consensus?.books||[]).map(b=>`<div>${esc(b.book)} · ${percent(b.probability)} · weight ${Number(b.weight).toFixed(2)} · vig ${Number(b.vigPercent).toFixed(2)}%</div>`).join('')}</details>`;}
  function evRows(live) {
    const c=host.getContext?.()||{},f=c.toolFilters||{},quotes=host.getState().quotes,markets=marketRowsOf(quotes),start=q=>Date.parse(q.startTime)||Infinity;
    return computeAdvancedEv(quotes,settings()).filter(r=>Boolean(r.quote.live)===live&&r.ev>0&&plausibleEv(r,markets,settings())&&quoteVisible(r.quote)&&contextMatch(r.quote)
      &&(!f.minEv||r.ev*100>=Number(f.minEv))&&(!f.minProb||r.fair*100>=Number(f.minProb))&&oddsWithin(r.quote.odds,f.evMinOdds||'',''))
      .sort((a,b)=>Number(Boolean(root().flags[b.quote.id]?.pin))-Number(Boolean(root().flags[a.quote.id]?.pin))||(c.sort==='event'?(a.quote.displayEvent||a.quote.event).localeCompare(b.quote.displayEvent||b.quote.event):c.sort==='odds'?decimal(b.quote.odds)-decimal(a.quote.odds):c.sort==='prob'?b.fair-a.fair:c.sort==='start'?start(a.quote)-start(b.quote):b.ev-a.ev));
  }
  function renderEv(live) {
    const rows=evRows(live);
    const context=host.getContext?.()||{};
    const body=rows.map(r=>{
      const q=r.quote,limit=[num(q.maxStake),q.exchange?num(q.liquidity):null].filter(v=>v!=null),rawStake=fractionalKellyStake(context.bankroll||5000,context.kelly??.25,r.fair,q.odds),stake=limit.length?Math.min(rawStake,...limit):rawStake;
      const signal=host.getState().quotes.filter(x=>x.exchange&&quoteAvailable(x,settings())&&marketIdentity(x)===marketIdentity(q)&&String(x.side).toLowerCase()===String(q.side).toLowerCase()).sort((a,b)=>Number(b.liquidity)-Number(a.liquidity))[0];
      return `<tr data-evx-quote="${esc(q.id)}"><td><strong class="evx-positive">${signed(r.ev)}</strong>${r.estimated?'<small>Projected threshold</small>':''}${r.conditionalOnNoPush?'<small>Conditional on no push</small>':''}</td><td><strong>${esc(label(q))}</strong><small>${esc(q.event)} · ${esc(q.sport)} · ${esc(q.period||'Full game')}</small><small>${qState(q)}</small>${signal?`<small>${esc(signal.book)} liquidity ${money(Number(signal.liquidity))}</small>${movement(signal)}`:''}</td><td>${esc(q.book)}<strong>${displayOdds(q.odds)}</strong></td><td>${percent(r.fair)}<small>Fair odds ${displayOdds(probabilityToAmerican(r.fair))}</small>${priceDiagnostic(r)}</td><td><strong>${money(stake)}</strong><small>Fractional Kelly estimate</small><small>${limit.length?`Limit ${money(Math.min(...limit))}`:'Limit not supplied'}</small><small>${esc(q.region||q.state||'Region not supplied')}</small><small>${esc(new Date(q.ts).toLocaleString())}</small></td><td>${controls(q,live?'ev-live':'ev-pre')}${btn('Add to parlay','parlay-add',q.id)}</td></tr>`;
    });
    return `<div class="evx-workspace"><div class="evx-summary"><strong>${rows.length} qualifying selections</strong><span>${settings().minSharpBooks} reference books minimum · ${esc(settings().devigMethod)} no-vig</span>${btn('Pricing settings','navigate','settings')}</div>${table(['EV','Event / selection','Book / price','Fair probability','Stake estimate','Actions'],body)}<p class="evx-note">Estimates use recorded prices and your reference-book settings. Suspended, expired, and stale prices are excluded; interpolation is labeled. Exchange liquidity describes available offers, not observed trades.</p></div>`;
  }
  function renderArbs(live) {
    const s=settings(), pool=host.getState().quotes.filter(q=>quoteVisible(q));
    const pairs=arbitrageRows(pool,live,s).flatMap(group=>group.pairs.map(best=>({best})));
    const entries=pairs.map(x=>({...x,plan:constrainedArb(x.best,Number(root().arbStake)||100)})).filter(x=>x.plan&&x.best.every(contextMatch)&&x.plan.margin*100>=Number(s.minArbPercent||0)&&x.plan.margin*100<=(num(s.maxArbPercent)??ARB_DEFAULT_MAX_PERCENT)&&(!(Number(s.minAvailableStake)>0)||x.plan.limitsKnown&&Number.isFinite(x.plan.maximumFeasibleTotal)&&x.plan.maximumFeasibleTotal>=Number(s.minAvailableStake))).sort((a,b)=>Number(b.best.some(q=>root().flags[q.id]?.pin))-Number(a.best.some(q=>root().flags[q.id]?.pin))||b.plan.margin-a.plan.margin);
    const mode=s.arbMode||'arbs';
    return `<div class="evx-workspace"><form data-suite-form="arb-options" class="evx-inline-form">${field('Total stake','arbStake',root().arbStake||100,'number','min="0.01" step="0.01" required')}${select('Opportunities','arbMode',[['arbs','Arbitrage'],['both','Arbitrage & middles'],['middles','Middles only']],mode)}<button type="submit">Apply</button></form>${mode!=='middles'?entries.map(({best,plan})=>panel(`${signed(plan.margin)} return · ${best[0].event}`,`<div class="evx-summary"><span>Total ${money(plan.actualTotal??plan.totalStake)}</span><span>Lowest outcome ${money(plan.minProfit??plan.profit)}</span><span>${plan.limitsKnown&&Number.isFinite(plan.maximumFeasibleTotal)?`Capacity ${money(plan.maximumFeasibleTotal)}`:'Some stake limits are unknown'}</span>${btn(best.every(q=>root().flags[q.id]?.pin)?'Unpin arb':'Pin arb','pin-arb',best[0].id,`data-hedge="${esc(best[1].id)}"`)}</div>${table(['Selection','Odds / movement','Stake','Actions'],best.map((q,i)=>`<tr><td>${esc(label(q))}<small>${esc(q.book)}</small></td><td>${displayOdds(q.odds)}${movement(q)}</td><td>${money(plan.stakes[i])}</td><td>${controls(q,'arbitrage')}</td></tr>`))}<div class="evx-actions">${btn('Track both sides','track-arb',best[0].id,`data-hedge="${esc(best[1].id)}"`)}${btn('Boost / bonus calculation','arb-promo',best[0].id,`data-hedge="${esc(best[1].id)}"`)}${btn('Hide arb','hide-arb',best[0].id,`data-hedge="${esc(best[1].id)}"`)}</div><p class="evx-note">Uses supplied limits and commissions. Rounded stakes may produce different results on each side.${plan.pushPossible?' A shared push can return both cash stakes.':''}</p>`)).join('')||'<div class="evx-empty">No qualifying arbitrage in available records.</div>':''}${mode!=='arbs'?renderMiddles(live):''}</div>`;
  }
  function movement(q){const previous=host.getState().history.filter(h=>h.quoteId===q.id&&Date.parse(h.ts)<Date.parse(q.ts)&&Number.isFinite(decimal(h.odds))).sort((a,b)=>Date.parse(b.ts)-Date.parse(a.ts))[0];return previous?`<small>${displayOdds(previous.odds)} → ${displayOdds(q.odds)}${String(previous.line)!==String(q.line)?` · line ${esc(previous.line)} → ${esc(q.line)}`:''}</small>`:'<small>No earlier observation</small>';}
  function renderMiddles(live=null) {
    const pool=host.getState().quotes.filter(q=>quoteVisible(q));
    const max=(num(settings().maxArbPercent)??ARB_DEFAULT_MAX_PERCENT)/100,rows=(live===null?[false,true]:[live]).flatMap(mode=>middleRows(pool,mode,settings())).filter(x=>contextMatch(x.over)&&contextMatch(x.under)&&x.cost>=-max);
    return panel('Middle windows',(rows.length>MIDDLE_ROWS?`<p class="evx-note">Showing the widest ${MIDDLE_ROWS} of ${rows.length} windows.</p>`:'')+table(['Market','First side','Second side','Outcomes'],rows.slice(0,MIDDLE_ROWS).map(x=>`<tr><td>${esc(x.over.event)}<small>${esc(x.window)}</small></td><td>${esc(x.over.side)} ${esc(x.over.line)} · ${displayOdds(x.over.odds)}<small>${esc(x.over.book)}</small></td><td>${esc(x.under.side)} ${esc(x.under.line)} · ${displayOdds(x.under.odds)}<small>${esc(x.under.book)}</small></td><td>${btn('Calculate outcomes','middle',x.over.id,`data-hedge="${esc(x.under.id)}"`)}</td></tr>`)),'Enter a final total or selection margin to inspect wins, losses, and pushes.');
  }
  function renderSettings() {
    const s=settings(),books=[...new Set(host.getState().quotes.map(q=>q.book))].sort();
    // Grouped settings: a heading and short description beside each set of fields.
    const group=(title,note,body,cls='')=>`<section class="evs-group ${cls}"><header><h4>${esc(title)}</h4><p>${esc(note)}</p></header><div class="evx-fields evs-fields">${body}</div></section>`;
    const toggle=(title,note,name,checked)=>`<label class="evs-toggle"><input type="checkbox" role="switch" name="${name}" ${checked?'checked':''}><span class="evs-toggle-copy"><strong>${esc(title)}</strong><small>${esc(note)}</small></span></label>`;
    return `<div class="evx-workspace evs-settings">${panel('Pricing, availability & filters',`<form data-suite-form="settings" class="evs-form">`
      +group('Fair value','How consensus no-vig prices are built from reference books.',`${select('No-vig method','devigMethod',DEVIG_METHODS,s.devigMethod)}${field('Minimum reference books','minSharpBooks',s.minSharpBooks,'number','min="1" max="30" required')}${field('Maximum book vig %','maxVigPercent',s.maxVigPercent,'number','min="0" max="100" step="0.1" required')}`)
      +group('EV & odds limits','Blank upper and lower limits are unrestricted.',`${field('Minimum EV %','minEvPercent',s.minEvPercent,'number','step="0.1"')}${field('Maximum EV %','maxEvPercent',s.maxEvPercent,'number','step="0.1"')}${field('Minimum American odds','minOdds',s.minOdds,'number','step="1"')}${field('Maximum American odds','maxOdds',s.maxOdds,'number','step="1"')}`)
      +group('Arbitrage','Return range and the smallest stake a pair must support.',`${field('Minimum arb %','minArbPercent',s.minArbPercent,'number','step="0.1"')}${field('Maximum arb %','maxArbPercent',s.maxArbPercent,'number','step="0.1"')}${field('Minimum available arb stake','minAvailableStake',s.minAvailableStake,'number','min="0"')}`)
      +group('Liquidity & freshness','Exchange depth and how long observed prices stay usable.',`${field('Minimum exchange liquidity','minLiquidity',s.minLiquidity,'number','min="0"')}${field('Live max age (seconds)','liveMaxAgeSeconds',s.liveMaxAgeSeconds,'number','min="1" max="3600" required')}${field('Pregame max age (seconds)','pregameMaxAgeSeconds',s.pregameMaxAgeSeconds,'number','min="1" max="604800" required')}`)
      +group('Scope','Limit every tool to a league, market, side, region or game state.',`${field('League','league',s.league)}${field('Market','market',s.market)}${field('Bet side','side',s.side)}${field('State / region','region',s.region)}${select('Game status','gameStatus',[['','All'],['pregame','Pregame'],['live','Live'],['stoppage','Game stoppage'],['in-play','In play']],s.gameStatus)}`)
      +group('Display','Odds format, what a tap does, and how often saved records refresh.',`${select('Odds format','oddsFormat',['american','decimal','fractional'],s.oddsFormat)}${select('Card tap action','cardTap',[['expand','Expand'],['pin','Pin'],['pin-expand','Pin and expand']],s.cardTap)}${select('Refresh saved records','autoRefresh',[['0','Off'],['15','15 seconds'],['30','30 seconds'],['60','60 seconds']],s.autoRefresh)}`)
      +`<section class="evs-group evs-options"><header><h4>Options</h4><p>Estimates, weighting and visibility.</p></header><div class="evs-toggles">${toggle('Estimate between prop thresholds','Interpolate a fair price when only neighbouring lines exist.','allowProjection',s.allowProjection)}${toggle('Weight exchanges by liquidity','Deeper exchange markets count more toward consensus.','liquidityWeighting',s.liquidityWeighting)}${toggle('Hide already-taken bets','Remove selections you have marked as taken.','hideTaken',s.hideTaken)}${toggle('Show hidden selections','Bring back selections you hid.','showHidden',s.showHidden)}</div></section>`
      +`<footer class="evs-savebar"><p>Refreshing reevaluates saved observations; it does not fetch live odds.</p><button type="submit" class="evx-primary">Save settings</button></footer></form>`,'Reference books, weighting, limits and display preferences used by every market tool.')}${panel('Sharp-book rules',`<form data-suite-form="book-rule"><div class="evx-fields">${select('Book','book',books,'')}${field('Weight','weight',1,'number','min="0.01" max="100" step="0.01" required')}${field('Sport scope (blank = all)','sport')}${field('League scope','league')}${field('Market scope','market')}${check('Required reference','required',false)}${check('Enabled','enabled',true)}</div><button type="submit">Add rule</button></form>${table(['Book','Scope','Weight','Required',''],(s.bookRules||[]).map((r,i)=>`<tr><td>${esc(r.book)}${r.enabled===false?' (disabled)':''}</td><td>${esc([r.sport,r.league,r.market].filter(Boolean).join(' / ')||'All markets')}</td><td>${esc(r.weight)}</td><td>${r.required?'Yes':'Optional'}</td><td>${btn('Remove','remove-rule',String(i))}</td></tr>`))}`,'With no rules, all other complete books are references. Once rules exist, only enabled matching rules contribute. The offered book is excluded.')}${panel('Saved filters',`<form data-suite-form="preset" class="evx-inline-form">${field('Preset name','name','','text','required maxlength="80"')}<button type="submit">Save current settings</button></form>${table(['Preset','Tool',''],root().presets.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.tool)}</td><td>${btn('Load','preset-load',p.id)}${btn('Delete','preset-delete',p.id)}</td></tr>`))}`)}</div>`;
  }
  function renderControls() {
    let node=document.getElementById('ev-suite-controls');
    if(!node){node=document.createElement('section');node.id='ev-suite-controls';node.className='evx-toolbar';document.querySelector('.ev-shell').before(node);}
    const tool=host.getTool?.(), detailed=hasView(tool);
    const mode=nativeViews.has(tool)?`<div class="evx-view-toggle" aria-label="Market display">${btn(nativeLabel(tool),'view-mode','cards',`aria-pressed="${!detailed}"`)}${btn('Detailed analysis','view-mode','detailed',`aria-pressed="${detailed}"`)}</div>`:'';
    node.innerHTML=`<nav aria-label="Workspace features">${btn('Pricing & filters','navigate','settings')}${btn('Alerts','navigate','alerts')}${btn('Performance','navigate','performance')}<details class="evx-tools-menu"><summary>All tools</summary><div>${[['Markets','odds','Odds Screen'],['Builders','parlay','Parlay builder'],['Records','tracker','Bet tracker'],...EV_SUITE_TOOLS].map(([,key,title])=>btn(esc(title),'navigate',key,tool===key?'aria-current="page"':'')).join('')}</div></details></nav><div class="evx-toolbar-end">${mode}${root().presets.length?`<label class="evx-preset-label"><span class="sr-only">Saved filter</span><select data-suite-preset><option value="">Saved filters</option>${root().presets.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>`:''}${btn('Save view','save-view')}${btn('Install app','install')}</div>${message?`<p class="evx-feedback" role="status">${esc(message)}</p>`:''}`;
  }
  function ensureDialog() {let d=document.getElementById('evx-dialog');if(!d){d=document.createElement('dialog');d.id='evx-dialog';d.className='evx-dialog';d.setAttribute('aria-labelledby','evx-dialog-title');document.body.append(d);d.addEventListener('click',handleEvent);d.addEventListener('submit',handleEvent);}return d;}
  function mount(){if(host.getBuilderIds)root().builderIds=[...host.getBuilderIds()];renderControls();const fields=document.querySelector('[data-suite-form="watch"] .evx-fields');if(fields&&!fields.querySelector('[name="presetId"]'))fields.insertAdjacentHTML('afterbegin',select('Saved view to watch','presetId',[['','Use current pricing'],...root().presets.map(p=>[p.id,p.name])],''));}
  function openDialog(title,content,context={}) {dialogContext=context;const d=ensureDialog();d.innerHTML=`<header><h2 id="evx-dialog-title">${esc(title)}</h2>${btn('Close','close-dialog')}</header><div class="evx-dialog-body">${content}<p class="evx-feedback" data-suite-error role="alert"></p></div>`;if(!d.open)d.showModal();}
  function error(e) {const target=document.querySelector('#evx-dialog[open] [data-suite-error]');if(target)target.textContent=e.message;else{message=e.message;renderControls();}}
  function notify(text) {message=text;renderControls();}
  function getQuote(quoteId) {return host.getState().quotes.find(q=>q.id===quoteId);}
  function setFlag(quoteId,key){const flags=root().flags[quoteId]??={};flags[key]=!flags[key];save();}

  function parlayModel() {
    const pool=host.getState().quotes,legs=root().builderIds.map(getQuote).filter(Boolean).map(q=>({quote:q,probability:consensusPrice(q,pool,settings()).probability}));
    const config=root().toolSettings.parlay||{};
    return {legs,config,result:advancedParlay(legs,{jointProbability:num(config.jointProbability),offeredDecimal:num(config.offeredDecimal)})};
  }
  function renderParlay() {
    const {legs,config,result}=parlayModel();
    const pool=host.getState().quotes,markets=marketRowsOf(pool),candidates=computeAdvancedEv(pool,settings()).filter(r=>r.ev>0&&plausibleEv(r,markets,settings())&&quoteVisible(r.quote)&&contextMatch(r.quote)&&!root().builderIds.includes(r.quote.id));
    return `<div class="evx-workspace">${panel('Build a parlay',`${table(['Leg','Book / odds','Fair probability',''],legs.map(({quote:q,probability})=>`<tr><td>${esc(label(q))}</td><td>${esc(q.book)} ${displayOdds(q.odds)}</td><td>${percent(probability)}</td><td>${btn('Remove','parlay-remove',q.id)}${btn('Bet link','link',q.id)}</td></tr>`))}<form data-suite-form="parlay-options"><div class="evx-fields">${field('Stake','stake',config.stake||10,'number','min="0.01" step="0.01" required')}${field('Actual combined decimal odds (optional)','offeredDecimal',config.offeredDecimal,'number','min="1.0001" step="any"')}${field('Joint win probability, 0–1 (optional)','jointProbability',config.jointProbability,'number','min="0" max="1" step="any"')}</div><button type="submit">Calculate parlay</button></form>${result?`<div class="evx-stats"><div><span>Combined odds</span><strong>${result.payout.toFixed(3)}</strong></div><div><span>Win probability</span><strong>${percent(result.probability)}</strong></div><div><span>Expected return</span><strong>${signed(result.ev)}</strong></div><div><span>Expected profit</span><strong>${money(result.ev*Number(config.stake||10))}</strong></div></div><p class="evx-note">${esc(result.probabilityBasis)}. ${esc(result.priceBasis)}.</p>${btn('Track parlay','parlay-track')}${btn('Open supported slip link','parlay-link')}`:'<p class="evx-note">Choose at least two distinct legs. Related legs need a supplied joint probability and actual combined price. Legs from different books need an actual combined price from the destination book.</p>'}`,'Independent-leg estimates assume outcomes do not affect each other. Same-event and tagged correlations are flagged.')}${panel('Qualifying +EV legs',table(['Selection','Book / price','EV',''],candidates.map(r=>`<tr><td>${esc(label(r.quote))}</td><td>${esc(r.quote.book)} ${displayOdds(r.quote.odds)}</td><td>${signed(r.ev)}</td><td>${btn('Add leg','parlay-add',r.quote.id)}</td></tr>`)))}</div>`;
  }
  function renderAlerts() {
    return `<div class="evx-workspace">${panel('Your saved watches',`<div class="evx-actions">${btn('Evaluate saved data now','evaluate-alerts')}${btn('Enable browser notifications','notifications')}${btn('Mark all read','alerts-read')}</div>${table(['Watch','Threshold / scope','Delivery',''],root().watchRules.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.kind)}</small></td><td>${esc(r.threshold)}${['ev','arb','smart'].includes(r.kind)?'%':''}<small>${esc([r.sport,r.book,r.market].filter(Boolean).join(' / ')||'All matching records')}</small></td><td>${esc(r.channel)}<small>${r.cooldown}s cooldown · ${r.enabled?'Enabled':'Paused'}</small></td><td>${btn(r.enabled?'Pause':'Enable','watch-toggle',r.id)}${btn('Delete','watch-delete',r.id)}</td></tr>`))}`,'Local watches evaluate available observations while this page is open. Push delivery to other devices and Discord will require the upcoming service connection.')}${panel('Create a watch',`<form data-suite-form="watch"><div class="evx-fields">${field('Name','name','','text','maxlength="80" required')}${select('Signal','kind',[['ev','Positive EV'],['arb','Arbitrage'],['fantasy','Fantasy props'],['smart','Recorded price movement'],['lineups','Lineup change'],['wallets','Followed-wallet fill']], 'ev')}${field('Minimum EV / arb %, movement points or fantasy edge (pts)','threshold',1,'number','min="0" step="0.1" required')}${field('Sport','sport')}${field('Book / app','book')}${field('Market contains','market')}${field('Minimum liquidity','minLiquidity',0,'number','min="0" step="0.01"')}${field('Cooldown in seconds','cooldown',300,'number','min="30" max="86400" required')}${select('Requested delivery','channel',[['in-app','In app'],['browser','Browser notification'],['discord','Discord (connection pending)'],['mobile','Mobile push (connection pending)']],'in-app')}</div><button type="submit">Save watch</button></form>`)}${panel('Alert history',table(['Time','Signal','Delivery'],root().alertLog.slice(0,150).map(a=>`<tr><td>${esc(new Date(a.ts).toLocaleString())}${a.read?'':'<small>Unread</small>'}</td><td>${esc(a.message)}</td><td>${esc(a.delivery)}</td></tr>`)))}</div>`;
  }
  function evaluateWatches() {
    const state=host.getState(),stamp=Date.now();let added=0;
    for(const rule of root().watchRules) {
      if(!rule.enabled||stamp-Number(rule.lastAt||0)<Number(rule.cooldown||300)*1000)continue;
      const preset=root().presets.find(p=>p.id===rule.presetId),cfg=preset?.settings||settings(),ctx=preset?.hostContext||{};
      const matches=(q,skipLiquidity=false)=>(!rule.sport||String(q.sport||'').toLowerCase()===rule.sport.toLowerCase())&&(!rule.book||String(q.book||q.app||q.platform||'').toLowerCase()===rule.book.toLowerCase())&&(!rule.market||String(q.market||'').toLowerCase().includes(rule.market.toLowerCase()))&&(skipLiquidity||!(rule.minLiquidity>0)||Number(q.liquidity)>=rule.minLiquidity)&&(!ctx.sport||q.sport===ctx.sport)&&(!ctx.league||(q.league||q.sport)===ctx.league)&&(!ctx.marketType||q.type===ctx.marketType)&&(!ctx.books||ctx.books.includes(q.book||q.app))&&(!ctx.search||[q.event,q.player,q.market,q.side,q.book||q.app].some(v=>String(v||'').toLowerCase().includes(String(ctx.search).toLowerCase())));
      let candidates=[];
      // Keys name a selection and its price, not the rescrape time: an unchanged price never alerts twice.
      if(rule.kind==='ev'){const markets=marketRowsOf(state.quotes);candidates=computeAdvancedEv(state.quotes,{...cfg,minEvPercent:Math.max(Number(cfg.minEvPercent)||0,rule.threshold)}).filter(r=>r.ev>0&&plausibleEv(r,markets,cfg)&&matches(r.quote)).map(r=>({key:r.quote.id+':'+r.quote.odds,text:`${label(r.quote)} at ${r.quote.book}: ${signed(r.ev)} EV`}));}
      if(rule.kind==='arb')candidates=[false,true].flatMap(l=>arbitrageRows(state.quotes.filter(q=>quoteAvailable(q,cfg)),l,cfg)).flatMap(group=>group.pairs.map(best=>({best,plan:constrainedArb(best,100)}))).filter(r=>r.plan&&r.plan.margin*100>=Math.max(rule.threshold,Number(cfg.minArbPercent)||0)&&r.plan.margin*100<=(num(cfg.maxArbPercent)??ARB_DEFAULT_MAX_PERCENT)&&r.best.every(q=>matches(q))).map(r=>({key:r.best.map(q=>q.id+':'+q.odds).join('|'),text:`${r.best[0].displayEvent||r.best[0].event}: ${signed(r.plan.margin)} arb`}));
      if(rule.kind==='fantasy')candidates=fantasy.alertCandidates({threshold:rule.threshold,minLiquidity:rule.minLiquidity,filters:preset?.fantasyFilters}).filter(r=>matches(r.pick,true));
      if(rule.kind==='smart')for(const q of state.quotes.filter(q=>q.exchange&&quoteAvailable(q,cfg)&&matches(q)&&!(root().marketViews?.hiddenExchanges||[]).includes(q.book))) {
        const history=state.history.filter(h=>h.quoteId===q.id&&Date.parse(h.ts)<Date.parse(q.ts)&&h.line===q.line&&Number.isFinite(decimal(h.odds))).sort((a,b)=>Date.parse(a.ts)-Date.parse(b.ts));
        if(history.length){const change=(implied(q.odds)-implied(history[0].odds))*100;if(Math.abs(change)>=rule.threshold)candidates.push({key:q.id+':'+q.odds,text:`${q.book}: ${label(q)} implied probability moved ${change.toFixed(1)} percentage points`});}
      }
      if(rule.kind==='lineups')candidates=(root().operations?.lineups||[]).flatMap(change=>state.quotes.filter(q=>matches(q)&&quoteAvailable(q,cfg)&&q.sport===change.sport&&q.event===change.event&&q.market===change.market&&String(q.side).toLowerCase()===String(change.selection).toLowerCase()&&String(q.line??'')===String(change.line??'')&&(!q.player||q.player===change.player)&&Date.parse(q.ts)<Date.parse(change.ts)&&num(change.probability)!=null&&change.probability*decimal(q.odds)-1>=rule.threshold/100).map(q=>({key:change.id+q.id+q.ts,text:`${change.player}: ${change.previous} → ${change.next}; ${q.book} ${signed(change.probability*decimal(q.odds)-1)} from supplied projection`})));
      if(rule.kind==='wallets'){const follows=new Set((root().operations?.wallets||[]).filter(w=>w.followed!==false).map(w=>w.id));candidates=(root().operations?.entries||[]).filter(q=>q.kind==='fill'&&follows.has(q.walletId)&&matches(q)).map(q=>({key:q.id+q.ts,text:`Wallet fill: ${q.event} ${q.selection} at ${q.price}¢`}));}
      const seen=new Set(rule.seen||[]),next=candidates.filter(c=>!seen.has(c.key)).slice(0,5);
      for(const candidate of next){seen.add(candidate.key);const delivery=['discord','mobile'].includes(rule.channel)?'In app · requested delivery awaits connection':rule.channel==='browser'&&globalThis.Notification?.permission==='granted'?'Browser + in app':'In app';root().alertLog.unshift({id:id(),ruleId:rule.id,message:candidate.text,ts:new Date().toISOString(),read:false,delivery});added++;if(delivery==='Browser + in app')try{new Notification(rule.name,{body:candidate.text,tag:rule.id,icon:'/favicon.svg'});}catch{/* Browser delivery unavailable; record remains in app. */}}
      if(next.length)rule.lastAt=stamp;rule.seen=[...seen].slice(-1000);
    }
    root().alertLog=root().alertLog.slice(0,300);save(false);return added;
  }
  function openLink(q) {
    const region=settings().region,regional=q.links?.[region],url=safeURL(regional?.prefillUrl||regional?.eventUrl||q.prefillUrl||q.betUrl||q.eventUrl);
    openDialog('Check the selection before continuing',`<h3>${esc(label(q))}</h3><p>${esc(q.book)} · ${displayOdds(q.odds)} · ${esc(region||q.region||'Region not specified')}</p><p>Confirm the player or team, line, odds, and settlement terms in the destination app. The recorded quote may have changed.</p>${url?`<a class="evx-primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open ${esc(q.book)}</a>`:'<p>No provider-supported link is attached to this record. Add its event URL in record details.</p>'}<div class="evx-actions">${btn('Track this bet','link-track',q.id)}${btn('Edit record details','quote-meta',q.id)}${btn('Report a bad link','report',q.id)}</div>`,{q});
  }
  function openMetadata(q) {
    openDialog('Market record details',`<form data-suite-form="quote-meta"><div class="evx-fields">${field('League','league',q.league)}${field('Period / quarter','period',q.period)}${field('State / region','region',q.region)}${field('Maximum stake','maxStake',q.maxStake,'number','min="0.01" step="0.01"')}${field('Exchange liquidity','liquidity',q.liquidity,'number','min="0" step="0.01"')}${field('Commission %','commissionPercent',q.commissionPercent,'number','min="0" max="99" step="0.01"')}${field('Expires at (ISO time)','expiresAt',q.expiresAt)}${field('Game start (ISO time)','startTime',q.startTime)}${field('Event URL','eventUrl',q.eventUrl,'url')}${field('Supported prefilled URL','prefillUrl',q.prefillUrl,'url')}${check('Suspended','suspended',q.suspended)}${check('Live','live',q.live)}</div><label>Supplied game state (JSON)<textarea name="gameState" rows="6">${esc(JSON.stringify(q.gameState||{},null,2))}</textarea></label><p class="evx-note">Fields: awayScore, homeScore, clock, period, inPlay, down, distance, inning, count, runners, fouls, timeouts, cards, penalties.</p><button type="submit">Save record details</button></form>`,{q});
  }
  // Middles open on a score inside the window so the calculator shows a result immediately.
  function windowScore(a,b){const x=Number(a?.line),y=Number(b?.line);if(!Number.isFinite(x)||!Number.isFinite(y))return '';const low=a.type==='spread'?-x:x,high=y,mid=(low+high)/2;return Number.isInteger(mid)?mid:Math.round(mid*2)/2;}
  function outcomeDialog(kind,a,b,result=null,values={}) {
    const isMiddle=kind==='middle';
    openDialog(isMiddle?'Middle outcome calculator':'Arbitrage promotion calculator',`<p>${esc(label(a))} / ${esc(label(b))}</p><form data-suite-form="${kind}"><div class="evx-fields">${field(isMiddle?'First stake':'Total stake','stake',values.stake||100,'number','min="0.01" step="0.01" required')}${isMiddle?field('Second stake','stakeB',values.stakeB||100,'number','min="0.01" step="0.01" required')+field('Final total / first selection margin','score',values.score??windowScore(a,b),'number','step="any" required'):select('Stake treatment','bonusIndex',[['-1','Both cash'],['0','First leg is bonus'],['1','Second leg is bonus']],values.bonusIndex??-1)}${field('First-side profit boost %','boostPercent',values.boostPercent||0,'number','min="0" max="1000" step="0.1"')}</div><button type="submit">Calculate outcomes</button></form>${result?`<div class="evx-result"><strong>${money(isMiddle?result.profit:result.minProfit)} ${isMiddle?'net result':'minimum net outcome'}</strong><p>${isMiddle?`First: ${esc(result.a.result)} (${money(result.a.profit)}); second: ${esc(result.b.result)} (${money(result.b.profit)})`:`Stakes: ${result.stakes.map(money).join(' / ')} · outcome profits: ${result.profits.map(money).join(' / ')}${result.pushPossible?' · a shared push returns cash stakes':''}`}</p></div>`:''}<div class="evx-actions">${btn('Track first leg','track',a.id,`data-tool="${isMiddle?'middles':'arbitrage'}"`)}${btn('Track second leg','track',b.id,`data-tool="${isMiddle?'middles':'arbitrage'}"`)}</div>`,{a,b});
  }
  function renderWorkflow(tool) {if(['tracker','performance'].includes(tool))return ledger.render(tool);if(tool==='parlay')return renderParlay();if(tool==='alerts')return renderAlerts();if(tool==='fantasy-lab')return fantasy.render();return '';}
  function handleWorkflowEvent(event) {
    if(ledger.handleEvent(event)||fantasy.handleEvent(event))return true;
    const target=event.target;
    if(event.type==='change'&&target.matches('[data-suite-preset]')){loadPreset(target.value);return true;}
    if(event.type==='submit') {
      const form=target.closest('[data-suite-form]');if(!form)return false;event.preventDefault();if(!form.reportValidity())return true;
      const values=Object.fromEntries(new FormData(form)),kind=form.dataset.suiteForm;
      if(kind==='settings') {const next={...settings()};for(const k of Object.keys(values))next[k]=typeof defaults[k]==='number'||defaults[k]===null?num(values[k]):values[k];for(const k of ['allowProjection','liquidityWeighting','hideTaken','showHidden'])next[k]=form.elements[k].checked;for(const [low,high] of [['minEvPercent','maxEvPercent'],['minArbPercent','maxArbPercent'],['minOdds','maxOdds']])if(num(next[low])!=null&&num(next[high])!=null&&next[low]>next[high])throw Error('Each maximum must be at least its minimum.');root().settings=next;startRefresh();notify('Pricing and display settings saved.');}
      else if(kind==='book-rule'){if(!values.book)throw Error('Add a quote before configuring its reference book.');root().settings.bookRules=[...(settings().bookRules||[]),{...values,weight:Number(values.weight),enabled:form.elements.enabled.checked,required:form.elements.required.checked}];}
      else if(kind==='preset'){const mv={...root().marketViews};delete mv.events;root().presets.push({id:id(),name:values.name.trim(),tool:dialogContext?.presetTool||host.getTool?.()||'ev-pre',settings:structuredClone(settings()),hostContext:host.getContext?.(),marketViews:structuredClone(mv),ledgerFilters:ledger.getFilters?.(),fantasyFilters:fantasy.getFilters?.(),operationsFilters:operations.getFilters?.(),createdAt:new Date().toISOString()});if(ensureDialog().open)ensureDialog().close();notify('View and filters saved.');}
      else if(kind==='arb-options'){root().arbStake=Number(values.arbStake);root().settings.arbMode=values.arbMode;}
      else if(kind==='parlay-options'){root().toolSettings.parlay={stake:Number(values.stake),offeredDecimal:num(values.offeredDecimal),jointProbability:num(values.jointProbability)};}
      else if(kind==='watch'){root().watchRules.push({...values,id:id(),threshold:Number(values.threshold),cooldown:Number(values.cooldown),minLiquidity:Number(values.minLiquidity),enabled:true,seen:[]});}
      else if(kind==='report'){root().operations??={};root().operations.reports??=[];root().operations.reports.unshift({id:id(),reference:dialogContext.q?.id||'',kind:({'Stale price':'stale line','Wrong settlement':'grading'})[values.kind]||values.kind.toLowerCase(),description:values.message,ts:new Date().toISOString(),status:'open',url:''});ensureDialog().close();notify('Report saved locally. Export it from Coverage when needed.');}
      else if(kind==='quote-meta'){const q=dialogContext.q,g=JSON.parse(values.gameState||'{}');if(!g||typeof g!=='object'||Array.isArray(g))throw Error('Game state must be a JSON object.');for(const k of ['expiresAt','startTime'])if(values[k]&&!Number.isFinite(Date.parse(values[k])))throw Error('Enter a valid ISO timestamp.');for(const k of ['eventUrl','prefillUrl'])if(values[k]&&!safeURL(values[k]))throw Error('Use an http or https destination.');for(const k of ['league','period','region','expiresAt','startTime','eventUrl','prefillUrl'])q[k]=values[k];for(const k of ['maxStake','liquidity','commissionPercent']){const n=num(values[k]);if(n==null)delete q[k];else q[k]=n;}q.suspended=form.elements.suspended.checked;q.live=form.elements.live.checked;q.gameState=g;ensureDialog().close();}
      else if(kind==='middle'||kind==='arb-promo'){const {a,b}=dialogContext;const boosted={...a,odds:(()=>{const d=1+(decimal(a.odds)-1)*(1+Number(values.boostPercent)/100);return d>=2?(d-1)*100:-100/(d-1);})()};const result=kind==='middle'?middleOutcomes(boosted,b,Number(values.stake),Number(values.stakeB),Number(values.score)):constrainedArb([a,b],Number(values.stake),{boostPercent:Number(values.boostPercent),bonusIndex:Number(values.bonusIndex)});if(!result)throw Error('No valid calculation for these stakes, limits, or market pair.');outcomeDialog(kind,a,b,result,values);return true;}
      save();return true;
    }
    if(event.type!=='click')return false;
    const button=target.closest('[data-suite-action]');
    if(!button){const row=target.closest('[data-evx-quote]');if(row&&!target.closest('button,a,input,summary,select,details')){const tap=settings().cardTap;if(tap==='pin'||tap==='pin-expand')setFlag(row.dataset.evxQuote,'pin');if(tap!=='pin')host.openComparison?.(row.dataset.evxQuote);return true;}return false;}
    event.preventDefault();const action=button.dataset.suiteAction,key=button.dataset.id,q=getQuote(key);
    if(action==='navigate')host.navigate(key);
    else if(action==='view-mode'){const tool=host.getTool?.();if(nativeViews.has(tool)){root().toolSettings[tool]={...root().toolSettings[tool],detailed:key==='detailed'};save();}}
    else if(action==='save-view')openDialog('Save this view',`<form data-suite-form="preset">${field('View name','name','','text','required maxlength="80"')}<button type="submit">Save filters</button></form>`,{presetTool:host.getTool?.()});
    else if(action==='close-dialog')ensureDialog().close();
    else if(action==='pin'||action==='hide'||action==='taken')setFlag(key,{pin:'pin',hide:'hidden',taken:'taken'}[action]);
    else if(action==='pin-arb'||action==='hide-arb'){const b=getQuote(button.dataset.hedge);if(q&&b){const prop=action==='pin-arb'?'pin':'hidden',value=action==='hide-arb'||![q,b].every(x=>root().flags[x.id]?.pin);for(const x of [q,b]){root().flags[x.id]??={};root().flags[x.id][prop]=value;}save();}}
    else if(action==='track-arb'){const b=getQuote(button.dataset.hedge);if(q&&b)openTracking([q,b],{tool:'arbitrage',stake:Number(root().arbStake)||100});}
    else if(action==='track'||action==='link-track'){if(q){ensureDialog().close();openTracking([q],{tool:button.dataset.tool||host.getTool?.()||'market',probability:consensusPrice(q,host.getState().quotes,settings()).probability});}}
    else if(action==='history'){if(q){root().marketViews={...root().marketViews,historySelection:JSON.stringify([marketIdentity(q,false),String(q.side||'').trim().toLowerCase(),'']),historyScope:'quote',historyQuote:q.id,historyPage:0};save(false);host.navigate('history');}}
    else if(action==='link'&&q)openLink(q);
    else if(action==='quote-meta'&&q)openMetadata(q);
    else if(action==='report')openDialog('Report this market record',`<form data-suite-form="report">${select('Issue','kind',['Incorrect line','Stale price','Bad link','Wrong settlement','Other'],'Incorrect line')}<label>Details<textarea name="message" rows="4" required maxlength="2000"></textarea></label><button type="submit">Save report</button></form>`,{q});
    else if(action==='parlay-add'){if(q&&!root().builderIds.includes(key))root().builderIds.push(key);save();notify('Selection added to Parlay builder.');}
    else if(action==='parlay-remove'){root().builderIds=root().builderIds.filter(x=>x!==key);save();}
    else if(action==='parlay-track'){const {legs,config,result}=parlayModel();if(!result)throw Error('Complete a valid parlay calculation first.');openTracking(legs.map(x=>x.quote),{type:'parlay',tool:'parlay',offeredDecimal:result.payout,oddsFormat:'decimal',probability:result.probability,stake:config.stake||10,selection:legs.map(x=>label(x.quote)).join(' + ')});}
    else if(action==='parlay-link'){const {legs}=parlayModel(),urls=[...new Set(legs.map(x=>safeURL(x.quote.parlayUrl)).filter(Boolean))];if(urls.length!==1||!legs.every(x=>safeURL(x.quote.parlayUrl)===urls[0]))throw Error('No shared provider-supported parlay URL is attached. Open the individual event links and confirm the combined ticket.');openDialog('Review the combined ticket',`<p>Check every selection, line, and combined price before placing a bet.</p><a class="evx-primary" href="${esc(urls[0])}" target="_blank" rel="noopener noreferrer">Open supplied parlay link</a>${btn('Track parlay','parlay-track')}`);}
    else if(action==='remove-rule'){root().settings.bookRules=settings().bookRules.filter((_,i)=>i!==Number(key));save();}
    else if(action==='preset-load')loadPreset(key);
    else if(action==='preset-delete'){root().presets=root().presets.filter(p=>p.id!==key);save();}
    else if(action==='watch-toggle'){const watch=root().watchRules.find(w=>w.id===key);if(watch)watch.enabled=!watch.enabled;save();}
    else if(action==='watch-delete'){root().watchRules=root().watchRules.filter(w=>w.id!==key);save();}
    else if(action==='evaluate-alerts'){const count=evaluateWatches();host.redraw();notify(`${count} new alerts from saved observations.`);}
    else if(action==='alerts-read'){root().alertLog.forEach(a=>a.read=true);save();}
    else if(action==='notifications'){if(!globalThis.Notification)throw Error('This browser does not support notifications. In-app alerts remain available.');Notification.requestPermission().then(permission=>notify(permission==='granted'?'Browser alerts enabled while the workspace is open.':'In-app alerts remain available.'));}
    else if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>{installPrompt=null;renderControls();});}else openDialog('Install VisualOdds',`<p>Open your browser menu and choose <strong>Install app</strong> or <strong>Add to Home Screen</strong> when available. On iOS, use Safari’s Share menu and Add to Home Screen.</p><p>Saved records remain in this browser. Native iOS and Android apps and cross-device sync will need separate integrations.</p>`);}
    else if(action==='middle'||action==='arb-promo'){const b=getQuote(button.dataset.hedge);if(q&&b)outcomeDialog(action,q,b);}
    else return false;
    return true;
  }
  function loadPreset(presetId){const preset=root().presets.find(p=>p.id===presetId);if(!preset)return;root().settings=structuredClone(preset.settings);if(preset.marketViews)root().marketViews={...root().marketViews,...structuredClone(preset.marketViews)};ledger.setFilters?.(preset.ledgerFilters,false);fantasy.setFilters?.(preset.fantasyFilters);operations.setFilters?.(preset.operationsFilters);startRefresh();save(false);host.navigate(preset.tool);host.restoreContext?.(preset.hostContext);host.redraw();notify(`Loaded ${preset.name}.`);}
  function validateImport(data) {
    const object=(value,label)=>{if(value!=null&&(typeof value!=='object'||Array.isArray(value)))throw Error(`${label} must be an object.`);};
    object(data.suite,'Suite');const s=data.suite||{};
    for(const k of ['settings','flags','betMeta','toolSettings','operations','marketViews','fantasyLab'])object(s[k],k);
    for(const k of ['presets','watchRules','alertLog','reports','builderIds'])if(s[k]!=null&&!Array.isArray(s[k]))throw Error(`${k} must be a list.`);
    if(s.settings?.bookRules!=null&&(!Array.isArray(s.settings.bookRules)||s.settings.bookRules.some(r=>!r||typeof r.book!=='string'||!(Number(r.weight)>0))))throw Error('Reference-book rules need a book and positive weight.');
    for(const p of s.presets||[]){if(typeof p.id!=='string'||typeof p.name!=='string')throw Error('Saved filters need IDs and names.');object(p.settings,'Preset settings');}
    for(const k of ['wallets','entries','lineups','offers','reports','affiliateRecords'])if(s.operations?.[k]!=null&&!Array.isArray(s.operations[k]))throw Error(`${k} must be a list.`);
    for(const k of ['history','tables','slips','selected'])if(s.fantasyLab?.[k]!=null&&!Array.isArray(s.fantasyLab[k]))throw Error(`Fantasy ${k} must be a list.`);
    for(const k of ['annotations','filters','settings','builder'])object(s.fantasyLab?.[k],`Fantasy ${k}`);
    for(const k of ['tables','slips'])for(const record of s.fantasyLab?.[k]||[]){if(!record||typeof record!=='object'||typeof record.id!=='string')throw Error(`Fantasy ${k} require records with IDs.`);if(k==='slips'&&(!Array.isArray(record.picks)||!Array.isArray(record.paytable)))throw Error('Fantasy slips require picks and payout rules.');if(k==='tables'&&(!Array.isArray(record.rules)||record.rules.some(n=>!Number.isFinite(Number(n))||Number(n)<0)))throw Error('Fantasy tables require nonnegative payout multipliers.');}
    for(const k of ['presets','watchRules','alertLog','reports'])if((s[k]||[]).some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error(`${k} require object records.`);
    for(const watch of s.watchRules||[]){if(!['ev','arb','fantasy','smart','lineups','wallets'].includes(watch.kind)||typeof watch.id!=='string'||typeof watch.name!=='string'||!(Number(watch.cooldown)>=30)||!(Number(watch.threshold)>=0))throw Error('Alert rules need a supported signal, name, cooldown and threshold.');for(const key of ['sport','book','market','presetId'])if(watch[key]!=null&&typeof watch[key]!=='string')throw Error('Alert filter values must be text.');if(watch.seen!=null&&!Array.isArray(watch.seen))throw Error('Alert seen records must be a list.');}
    for(const metadata of Object.values(s.betMeta||{})){object(metadata,'Bet metadata');for(const key of ['quoteSnapshots','legResults','paytable','exactHitProbabilities'])if(metadata?.[key]!=null&&!Array.isArray(metadata[key]))throw Error(`Bet ${key} must be a list.`);}
    for(const key of ['wallets','entries','lineups','offers','reports','affiliateRecords'])if((s.operations?.[key]||[]).some(record=>!record||typeof record!=='object'||Array.isArray(record)||typeof record.id!=='string'))throw Error(`${key} need object records with IDs.`);
    if((s.builderIds||[]).some(v=>typeof v!=='string'))throw Error('Parlay selections require string IDs.');
    for(const q of data.quotes||[]){for(const k of ['available','active','suspended','expired','stale','live'])if(q[k]!=null&&typeof q[k]!=='boolean')throw Error(`${k} must be true or false.`);object(q.gameState,'Game state');object(q.links,'Regional links');}
    if(data.personalBets!=null){if(!Array.isArray(data.personalBets))throw Error('Personal bets must be a list.');for(const b of data.personalBets){validateBet(b);if(!/^[a-zA-Z0-9-]{1,80}$/.test(b.id||'')||!Number.isFinite(Date.parse(b.updatedAt)))throw Error('Personal bets need a valid ID and updated time.');}}
  }
  function importLedger(data){const currentMeta=root().betMeta;data.suite??={};const incomingMeta=data.suite.betMeta||{},meta={...currentMeta};if(data.personalBets){const current=new Map(readBets(localStorage).map(b=>[b.id,b]));for(const b of data.personalBets){const old=current.get(b.id);if(!old||Date.parse(b.updatedAt)>Date.parse(old.updatedAt)){current.set(b.id,{...validateBet(b),id:b.id,updatedAt:b.updatedAt});if(incomingMeta[b.id])meta[b.id]=incomingMeta[b.id];}}writeBets(localStorage,[...current.values()]);}for(const [key,value]of Object.entries(incomingMeta))if(key.startsWith('legacy:'))meta[key]=value;data.suite.betMeta=meta;}
  const exportWorkspace=()=>({...host.getState(),personalBets:readBets(localStorage),exportedAt:new Date().toISOString()});
  function render(tool) {if(host.getBuilderIds)root().builderIds=[...host.getBuilderIds()];if(tool==='ledger')return ledger.render('tracker');if(['ev-pre','ev-live'].includes(tool))return renderEv(tool==='ev-live');if(['arb-pre','arb-live'].includes(tool))return renderArbs(tool==='arb-live');if(tool==='middles')return renderMiddles();if(tool==='settings')return renderSettings();if(['odds','history','sharp'].includes(tool))return markets.render({odds:'market-screen',history:'history',sharp:'smart-signals'}[tool]);if(['wallets','lineups','promotions','connections'].includes(tool))return operations.render(tool);return renderWorkflow(tool);}
  const owned=new Set(['ev-pre','ev-live','arb-pre','arb-live','middles','settings','odds','history','sharp','wallets','lineups','promotions','connections','performance','alerts','tracker','parlay','fantasy-lab']);
  function hasView(tool){return tool === 'ledger' || owned.has(tool) && (!nativeViews.has(tool) || root().toolSettings[tool]?.detailed === true);}
  function handleEvent(event) {try{if(operations.handleEvent(event)||markets.handleEvent(event))return true;return handleWorkflowEvent(event);}catch(e){event.preventDefault();error(e);return true;}}
  function startRefresh(){if(refreshTimer)clearInterval(refreshTimer);const seconds=Number(settings().autoRefresh);if(seconds>0)refreshTimer=setInterval(()=>{if(document.hidden||document.querySelector('dialog[open]'))return;lastRefresh=Date.now();evaluateWatches();if(document.fullscreenElement||document.activeElement?.matches('input,textarea,select,[contenteditable]'))return;host.redraw();},Math.max(15,seconds)*1000);}
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,select,[contenteditable]')){const search=document.querySelector('#ev-view input[type=search]')||document.getElementById('ev-search');if(search){e.preventDefault();search.focus();}}});
  let touchStart=null;
  document.addEventListener('touchstart',e=>{const row=e.target.closest('[data-evx-quote]');if(row&&!e.target.closest('button,a,input,select'))touchStart={id:row.dataset.evxQuote,x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY};},{passive:true});
  document.addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>90&&Math.abs(dy)<35)setFlag(touchStart.id,dx>0?'pin':'hidden');touchStart=null;},{passive:true});
  window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;renderControls();});
  if('serviceWorker' in navigator)navigator.serviceWorker.register('/ev-sw.js',{scope:'/ev'}).catch(()=>{});
  function heroStats(tool){const r=root(),cfg=settings();if(tool==='alerts')return [['Saved watches',r.watchRules.length],['Enabled',r.watchRules.filter(x=>x.enabled).length,true],['Unread alerts',r.alertLog.filter(a=>!a.read).length]];if(tool==='settings')return [['Saved views',r.presets.length],['No-vig method',String(cfg.devigMethod).replace(/^./,c=>c.toUpperCase()),true],['Reference books',`${cfg.minSharpBooks}+`]];return [];}
  return {hasView,render,mount,heroStats,handleEvent,settings,quoteVisible,displayOdds,controls,evaluateWatches,trackQuote:(q,tool)=>openTracking([q],{tool}),startRefresh,exportWorkspace,validateImport,importLedger,probability:q=>consensusPrice(q,host.getState().quotes,settings()).probability};
}
